CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 REAL UNIQUE, c1 BLOB, c2 INT, c3, c4 BLOB);
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 REAL DEFAULT 'd', c1 REAL CHECK(c1 IS NULL OR length(c1) < 40), c2 TEXT NOT NULL DEFAULT 0, ref INTEGER REFERENCES t0(id)) STRICT;
INSERT OR IGNORE INTO t1(c0, c1, c2, ref) VALUES(-18.578, 20.070, '1e3', NULL);
INSERT OR IGNORE INTO t1(c0, c1, c2, ref) VALUES(15.958, -44.072, '1e3', NULL);
INSERT OR IGNORE INTO t1(c0, c1, c2, ref) VALUES(19.610, 31.697, 'upsilon', 6);
SELECT length('nu'), upper('nu'), lower('nu'), substr('nu', 3, 5), instr('nu', 'psi'), replace('nu', 'e', '_'), trim('nu'), ltrim('nu', 'ab'), hex('nu'), quote('nu'), unicode('nu'), 'nu' LIKE '_', 'nu' GLOB '?', char(78, 946), 'nu' || 'psi', 'nu' < 'psi', 'nu' = 'psi' COLLATE NOCASE;
SELECT length('beta'), upper('beta'), lower('beta'), substr('beta', -1, 2), instr('beta', 'iota'), replace('beta', '', ''), trim('beta'), ltrim('beta', 'ab'), hex('beta'), quote('beta'), unicode('beta'), 'beta' LIKE '%', 'beta' GLOB 'a*', char(68, 229), 'beta' || 'iota', 'beta' < 'iota', 'beta' = 'iota' COLLATE NOCASE;
SELECT length('Lambda'), upper('Lambda'), lower('Lambda'), substr('Lambda', 1, 0), instr('Lambda', 'chi'), replace('Lambda', 'é', '_'), trim('Lambda'), ltrim('Lambda', 'ab'), hex('Lambda'), quote('Lambda'), unicode('Lambda'), 'Lambda' LIKE '%', 'Lambda' GLOB '*[a-m]*', char(66, 254), 'Lambda' || 'chi', 'Lambda' < 'chi', 'Lambda' = 'chi' COLLATE NOCASE;
SELECT length('naïve'), upper('naïve'), lower('naïve'), substr('naïve', 4, 0), instr('naïve', ' pad '), replace('naïve', '', ''), trim('naïve'), ltrim('naïve', 'ab'), hex('naïve'), quote('naïve'), unicode('naïve'), 'naïve' LIKE '%é%', 'naïve' GLOB '?', char(89, 566), 'naïve' || ' pad ', 'naïve' < ' pad ', 'naïve' = ' pad ' COLLATE NOCASE;
SELECT length('eta'), upper('eta'), lower('eta'), substr('eta', 3, 0), instr('eta', 'beta'), replace('eta', 'e', ''), trim('eta'), ltrim('eta', 'ab'), hex('eta'), quote('eta'), unicode('eta'), 'eta' LIKE '_', 'eta' GLOB '?', char(69, 968), 'eta' || 'beta', 'eta' < 'beta', 'eta' = 'beta' COLLATE NOCASE;
SELECT length('it''s'), upper('it''s'), lower('it''s'), substr('it''s', 2, 3), instr('it''s', 'nu'), replace('it''s', '', ''), trim('it''s'), ltrim('it''s', 'ab'), hex('it''s'), quote('it''s'), unicode('it''s'), 'it''s' LIKE '%', 'it''s' GLOB '*[a-m]*', char(81, 680), 'it''s' || 'nu', 'it''s' < 'nu', 'it''s' = 'nu' COLLATE NOCASE;
CREATE UNIQUE INDEX IF NOT EXISTS i18 ON t0(c2, id) WHERE c2 IS NOT NULL;
SELECT id, c2 FROM t0 WHERE c2 <= '0x1F' ORDER BY c2, id;
SELECT count(*) FROM t0 INDEXED BY i18 WHERE c2 IS NOT NULL;
REINDEX t0;
DROP INDEX IF EXISTS i18;
